from flask import Flask, request, jsonify, Response
import os
import json

app = Flask(__name__)
DATA_DIR = "/workdir/data"

def load_queues():
    path = os.path.join(DATA_DIR, "queues.json")
    if os.path.exists(path):
        with open(path, 'r') as f:
            data = json.load(f)
            return data
    return {}

def save_queues(queues):
    os.makedirs(DATA_DIR, exist_ok=True)
    path = os.path.join(DATA_DIR, "queues.json")
    with open(path, 'w') as f:
        json.dump(queues, f)

@app.route('/queues', methods=['POST'])
def create_queue():
    data = request.get_json() or {}
    name = data.get('name')
    if not name:
        return jsonify({"error": "name is required"}), 400
    queues = load_queues()
    queues[name] = []  # Initialize empty list for new queue
    save_queues(queues)
    return jsonify({"message": "queue created", "name": name}), 201

@app.route('/queues/<name>/messages', methods=['POST'])
def send_message(name):
    data = request.get_json() or {}
    content = data.get('content')
    if not content:
        return jsonify({"error": "content is required"}), 400
    queues = load_queues()
    if name not in queues:
        return jsonify({"error": "queue not found"}), 404
    queues[name].append(content)
    save_queues(queues)
    return jsonify({"message": "message sent"}), 201

@app.route('/queues/<name>/messages', methods=['GET'])
def consume_message(name):
    queues = load_queues()
    if name not in queues:
        return jsonify({"error": "queue not found"}), 404
    messages = queues[name]
    if not messages:
        return Response(status_code=204)  # 204 No Content for empty queue
    # FIFO: take the first message and remove it
    message = messages.pop(0)
    save_queues(queues)
    return jsonify({"content": message})

@app.route('/status', methods=['GET'])
def get_status():
    return jsonify({"status": "running"})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000)
