def create_queue(request: Request):
    body = request.json if request.headers.get("Content-Type") else {}
    if not body or not isinstance(body, dict):
        body = {}
    name = body.get("name")
    if not name:
        raise HTTPException(status_code=400, detail="name is required")
    queues = load_queues()
    queues[name] = []  # Initialize empty list for new queue
    save_queues(queues)
